-- Behavior tests for 086_disappearance_inferred_sales (D000070).
-- Run against a THROWAWAY database restored from the production schema
-- (pg_dump --schema-only), never against production data:
--   createdb pokoin_pipeline_test
--   pg_dump --schema-only prod | psql pokoin_pipeline_test
--   psql pokoin_pipeline_test -v ON_ERROR_STOP=1 \
--     -f oracle-postgres/tests/086_disappearance_inferred_sales.test.sql
-- Every test RAISEs on failure; a clean run prints only T<n> ok lines.

\set ON_ERROR_STOP on
\set QUIET on

delete from public.cardtrader_market_listing_removed_history where blueprint_id between 987001 and 987099;
delete from public.cardtrader_market_listing_snapshots where blueprint_id between 987001 and 987099;
delete from public.marketplace_price_observations where blueprint_id between 987001 and 987099;
delete from public.cardtrader_blueprint_population_daily where blueprint_id between 987001 and 987099;
delete from public.cardtrader_sold_daily where blueprint_id between 987001 and 987099;
delete from public.cardtrader_blueprint_listing_cache where blueprint_id between 987001 and 987099;

\set QUIET off
\echo 'T1: valid complete-book disappearance => provisional inferred sale + ghost cleanup'
\set QUIET on

insert into public.cardtrader_market_listing_snapshots (
  provider, external_listing_id, blueprint_id, seller_account_id, seller_account_name,
  quantity, condition, language, price, price_cents, currency, properties, raw_metadata,
  first_seen_at, last_seen_at, imported_at, updated_at
) values
    ('cardtrader','A1',987001,'111','Seller One',4,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz),
    ('cardtrader','A2',987001,'111','Seller One',2,'NM','en',12,1200,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz),
    ('cardtrader','A3',987001,'222','Seller Two',1,'SP','it',5,500,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz);

insert into public.cardtrader_blueprint_population_daily
  (blueprint_id, observed_day, listing_count, listed_quantity, seller_count)
values (987001, current_date-1, 3, 7, 2);

with settings as (select set_config('app.cardtrader_complete_book', '1', true))
select * from settings, lateral (
  select * from public.refresh_cardtrader_market_listing_snapshots(
'cardtrader', '[{"externalListingId": "A2", "blueprintId": 987001, "sellerAccountId": "111", "quantity": 2, "condition": "NM", "language": "en", "price": 12, "priceCents": 1200, "currency": "EUR", "properties": {}, "rawMetadata": {}}, {"externalListingId": "A3", "blueprintId": 987001, "sellerAccountId": "222", "quantity": 1, "condition": "SP", "language": "it", "price": 5, "priceCents": 500, "currency": "EUR", "properties": {}, "rawMetadata": {}}]'::jsonb, '[987001]'::jsonb, current_date-1, true, now(), false, false)
) refreshed;

do $$
begin
  assert (select count(*) from public.cardtrader_market_listing_removed_history
          where external_listing_id='A1' and archive_reason='inferred_sale'
            and status='provisional' and quantity=4) = 1, 'T1: A1 should be a provisional sale of 4 (stack delta 6-2)';
  assert (select count(*) from public.marketplace_price_observations
          where source='cardtrader_removed_sale'
            and source_item_id = 'cardtrader:A1:' || to_char(current_date-1,'YYYY-MM-DD') || ':inferred_sale') = 1, 'T1: A1 observation missing';
  assert (select count(*) from public.cardtrader_market_listing_snapshots
          where external_listing_id='A1') = 0, 'T1: A1 ghost must leave the live book';
  assert (select count(*) from public.cardtrader_market_listing_snapshots
          where blueprint_id=987001) = 2, 'T1: live book should hold A2+A3 only';
end $$;
\echo 'T1 ok'


\echo 'T2: partial (non-complete-book) observation never archives disappearances'
\set QUIET on
insert into public.cardtrader_market_listing_snapshots (
  provider, external_listing_id, blueprint_id, seller_account_id, seller_account_name,
  quantity, condition, language, price, price_cents, currency, properties, raw_metadata,
  first_seen_at, last_seen_at, imported_at, updated_at
) values
    ('cardtrader','B1',987002,'111','Seller One',4,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz);

with settings as (select set_config('app.cardtrader_complete_book', '', true))
select * from settings, lateral (
  select * from public.refresh_cardtrader_market_listing_snapshots(
'cardtrader', '[]'::jsonb, '[987002]'::jsonb, current_date-1, true, now(), false, false)
) refreshed;

do $$
begin
  assert (select count(*) from public.cardtrader_market_listing_removed_history
          where blueprint_id=987002 and archive_reason='inferred_sale') = 0, 'T2: partial fetch must not archive vanish';
  assert (select count(*) from public.cardtrader_market_listing_snapshots
          where external_listing_id='B1') = 1, 'T2: partial fetch must not delete from live book';
end $$;
\echo 'T2 ok'


