   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz),
  ('cardtrader','G6',987003,'111','Seller One',15,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz),
  ('cardtrader','G7',987003,'111','Seller One',15,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz),
  ('cardtrader','G8',987003,'111','Seller One',15,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz),
  ('cardtrader','G9',987003,'111','Seller One',15,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz),
  ('cardtrader','G10',987003,'111','Seller One',15,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz),
    ('cardtrader','G11',987003,'222','Seller Two',2,'SP','it',5,500,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz);

