tingId": "G10", "blueprintId": 987003, "sellerAccountId": "111", "quantity": 5, "condition": "NM", "language": "en", "price": 10, "priceCents": 1000, "currency": "EUR", "properties": {}, "rawMetadata": {}}]'::jsonb, '[987003]'::jsonb, current_date-1, true, now(), false, false)
) refreshed;

do $$
begin
  assert (select count(*) from public.cardtrader_market_listing_removed_history
          where external_listing_id='G11' and status='pending') = 1, 'T3: G11 must be pending';
  assert (select count(*) from public.marketplace_price_observations
          where source='cardtrader_removed_sale' and split_part(source_item_id,':',2)='G11') = 0, 'T3: pending must not project observations';
  assert (select count(*) from public.cardtrader_market_listing_snapshots
          where external_listing_id='G11') = 1, 'T3: frozen book keeps G11 row';
  assert (select quantity from public.cardtrader_market_listing_snapshots
          where external_listing_id='G1') = 15, 'T3: frozen book keeps pre-observation quantities';
  assert (select count(*) from public.cardtrader_market_listing_removed_history
          where blueprint_id=987003 and archive_reason='quantity_decreased') = 0, 'T3: frozen strip must not emit qty drips';
end $$;
\echo 'T3a ok (frozen)'

