\echo 'T5: disappearance then reappearance retracts exactly once (idempotent)'
\set QUIET on
insert into public.cardtrader_market_listing_snapshots (
  provider, external_listing_id, blueprint_id, seller_account_id, seller_account_name,
  quantity, condition, language, price, price_cents, currency, properties, raw_metadata,
  first_seen_at, last_seen_at, imported_at, updated_at
) values
    ('cardtrader','F1',987009,'111','Seller One',1,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz);
insert into public.cardtrader_blueprint_population_daily
  (blueprint_id, observed_day, listing_count, listed_quantity, seller_count)
values (987009, current_date-1, 1, 1, 1);

with settings as (select set_config('app.cardtrader_complete_book', '1', true))
select * from settings, lateral (
  select * from public.refresh_cardtrader_market_listing_snapshots(
'cardtrader', '[]'::jsonb, '[987009]'::jsonb, current_date-1, true, now(), false, false)
) refreshed;

do $$
begin
  assert (select count(*) from public.marketplace_price_observations
          where source='cardtrader_removed_sale' and split_part(source_item_id,':',2)='F1') = 1, 'T5: provisional sale expected';
end $$;

with settings as (select set_config('app.cardtrader_complete_book', '1', true))
select * from settings, lateral (
  select * from public.refresh_cardtrader_market_listing_snapshots(
'cardtrader', '[{"externalListingId": "F1", "blueprintId": 987009, "sellerAccountId": "111", "quantity": 1, "condition": "NM", "language": "en", "price": 11, "priceCents": 1100, "currency": "EUR", "properties": {}, "rawMetadata": {}}]'::jsonb, '[987009]'::jsonb, current_date, true, now(), false, false)
) refreshed;
with settings as (select set_config('app.cardtrader_complete_book', '1', true))
select * from settings, lateral (
  select * from public.refresh_cardtrader_market_listing_snapshots(
'cardtrader', '[{"externalListingId": "F1", "blueprintId": 987009, "sellerAccountId": "111", "quantity": 1, "condition": "NM", "language": "en", "price": 11, "priceCents": 1100, "currency": "EUR", "properties": {}, "rawMetadata": {}}]'::jsonb, '[987009]'::jsonb, current_date, true, now(), false, false)
) refreshed;

do $$
begin
  assert (select count(*) from public.cardtrader_market_listing_removed_history
          where external_listing_id='F1' and status='retracted') = 1, 'T5: exactly one retraction';
  assert (select count(*) from public.marketplace_price_observations
          where source='cardtrader_removed_sale' and split_part(source_item_id,':',2)='F1') = 0, 'T5: retracted observation deleted';
end $$;
\echo 'T5 ok'


\echo 'T6: replaying a refresh never duplicates sales; aggregation is idempotent'
\set QUIET on
insert into public.cardtrader_market_listing_snapshots (
  provider, external_listing_id, blueprint_id, seller_account_id, seller_account_name,
  quantity, condition, language, price, price_cents, currency, properties, raw_metadata,
  first_seen_at, last_seen_at, imported_at, updated_at
) values
    ('cardtrader','H1',987010,'111','Seller One',2,'NM','en',10,1000,'EUR','{}','{}',
   now()-interval '10 days', (current_date-1)::timestamptz, now()-interval '10 days', (current_date-1)::timestamptz);
insert into public.cardtrader_blueprint_population_daily
  (blueprint_id, observed_day, listing_count, listed_quantity, seller_count)
values (987010, current_date-1, 1, 2, 1);

with settings as (select set_config('app.cardtrader_complete_book', '1', true))
select * from settings, lateral (
  select * from public.refresh_cardtrader_market_listing_snapshots(
'cardtrader', '[]'::jsonb, '[987010]'::jsonb, current_date-1, true, now(), false, false)
) refreshed;
with settings as (select set_config('app.cardtrader_complete_book', '1', true))
select * from settings, lateral (
  select * from public.refresh_cardtrader_market_listing_snapshots(
'cardtrader', '[]'::jsonb, '[987010]'::jsonb, current_date-1, true, now(), false, false)
) refreshed;
select public.refresh_cardtrader_sold_daily(null);
select public.refresh_cardtrader_sold_daily(null);
do $$
begin
  assert (select count(*) from public.cardtrader_market_listing_removed_history
          where external_listing_id='H1') = 1, 'T6: replay must not duplicate history rows';
  assert (select count(*) from public.marketplace_price_observations
          where source='cardtrader_removed_sale' and split_part(source_item_id,':',2)='H1') = 1, 'T6: replay must not duplicate observations';
  assert (select sold_qty from public.cardtrader_sold_daily
          where blueprint_id=987010) = 2, 'T6: aggregation must be idempotent (sold 2)';
end $$;
\echo 'T6 ok'

\echo 'T7: sold_daily picks up projected sales (T1) and excludes retracted (T5)'
\set QUIET on
select public.refresh_cardtrader_sold_daily(null);
do $$
begin
  assert (select sold_qty from public.cardtrader_sold_daily
          where blueprint_id=987001) = 4, 'T7: blueprint 987001 sold 4';
  assert (select count(*) from public.cardtrader_sold_daily
          where blueprint_id=987009) = 0, 'T7: retracted episode must not be aggregated';
end $$;
\echo 'T7 ok'


