  quantity, condition, language, price, price_cents, currency, properties, raw_metadata,
  first_seen_at, last_seen_at, imported_at, last_snapshot_updated_at,
  removed_day, status, archive_reason, archive_metadata
) values
    ('cardtrader','RAP1',987021,987021,'1974042',
   'DR1','DRaconis','IT','public',
   1,'Played','it',5.08,508,'EUR','{}','{}',
   '2026-09-01','2026-09-10','2026-09-10','2026-09-10',
   current_date-9,'confirmed','dropped_from_cheapest_25',
   jsonb_build_object('reclassifiedBecause','cheap25_left_window_not_sold'));

\i /tmp/086_backfill_section.sql

do $$
begin
  assert (select count(*) from public.cardtrader_market_listing_removed_history
          where blueprint_id=987020 and status='invalid') = 1001, 'T8: mass-run rows must be invalid';
  assert (select count(*) from public.cardtrader_market_listing_removed_history
          where external_listing_id='RAP1' and archive_reason='inferred_sale'
            and status='confirmed') = 1, 'T8: cheap-25 leaver must backfill to inferred_sale';
  assert (select count(*) from public.marketplace_price_observations
          where source='cardtrader_removed_sale' and split_part(source_item_id,':',2)='RAP1') = 1, 'T8: backfilled sale must project an observation';
  assert (select count(*) from public.marketplace_price_observations
          where source='cardtrader_removed_sale' and blueprint_id=987020) = 0, 'T8: artifacts must not project observations';
end $$;
\echo 'T8 ok'


\echo 'T9: current-book cache refresh runs cleanly over the cleaned book'
\set QUIET on
with settings as (select set_config('app.pkn_usdt_price', '0.005', true))
select * from settings, lateral (
  select * from public.refresh_cardtrader_blueprint_listing_cache('cardtrader','[987001]'::jsonb, now())
) r;
do $$
begin
  -- Ghost cleanup already proved the live book holds exactly A2+A3 (T1).
  -- The cache builder is unchanged code with its own JS suite; here we assert
  -- it runs over the cleaned book without error and without resurrecting rows.
  assert (select count(*) from public.cardtrader_market_listing_snapshots
          where blueprint_id=987001) = 2, 'T9: live book unchanged by cache refresh';
end $$;
\echo 'T9 ok'

\set QUIET off
\echo 'ALL SOLD-PIPELINE BEHAVIOR TESTS PASSED'
